<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS delivery_documents (id INT AUTO_INCREMENT PRIMARY KEY,bon_commande_id INT NOT NULL,devis_id INT NOT NULL,numero_bl VARCHAR(120),fichier VARCHAR(255) NOT NULL,fichier_original VARCHAR(255) NOT NULL,date_signature DATE NOT NULL,uploaded_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_delivery_order(bon_commande_id),INDEX idx_delivery_quote(devis_id),INDEX idx_delivery_signed(date_signature)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
